namespace Ordering;

/// <summary>Handles product returns, the refunds they trigger and restocking.</summary>
public sealed class ReturnsHandler
{
    private readonly ReturnServices _services = new();

    public string ProcessReturn(Order order, Customer customer) =>
        _services.ProcessReturn(order, customer);

    public bool IsReturnable(Order order) =>
        _services.IsReturnable(order);

    public decimal ComputeRefund(Order order) =>
        _services.ComputeRefund(order);

    public void LogRefund(Order order, decimal amount) =>
        _services.LogRefund(order, amount);

    public int Restock(Order order) =>
        _services.Restock(order);
}

internal sealed class ReturnServices
{
    private readonly ReturnAcceptanceService _acceptance;
    private readonly RefundService _refunds = new();
    private readonly RestockService _restocking;

    public ReturnServices()
    {
        var inventory = new RestockInventory();
        _acceptance = new ReturnAcceptanceService(inventory);
        _restocking = new RestockService(inventory);
    }

    public string ProcessReturn(Order order, Customer customer) =>
        _acceptance.ProcessReturn(order, customer);

    public bool IsReturnable(Order order) =>
        _acceptance.IsReturnable(order);

    public decimal ComputeRefund(Order order) =>
        _refunds.ComputeRefund(order);

    public void LogRefund(Order order, decimal amount) =>
        _refunds.LogRefund(order, amount);

    public int Restock(Order order) =>
        _restocking.Restock(order);
}

internal sealed class ReturnAcceptanceService
{
    private readonly HashSet<string> _processedRefs = new(StringComparer.Ordinal);
    private readonly RestockInventory _inventory;

    public ReturnAcceptanceService(RestockInventory inventory)
    {
        _inventory = inventory;
    }

    public string ProcessReturn(Order order, Customer customer)
    {
        if (string.IsNullOrEmpty(order.Reference))
            return "missing reference";
        if (_processedRefs.Contains(order.Reference))
            return "already processed";
        if (order.Lines.Count == 0)
            return "nothing to return";
        if (customer.Tier == CustomerTier.Blocked)
            return "customer blocked";

        foreach (var line in order.Lines)
        {
            if (line.Quantity <= 0)
                continue;
            if (line.Quantity > 100)
                return "quantity too high";

            _inventory.Add(line.Sku, line.Quantity);
        }

        if (_inventory.Count == 0)
            return "no returnable lines";

        _processedRefs.Add(order.Reference);
        return "accepted";
    }

    public bool IsReturnable(Order order)
    {
        if (string.IsNullOrEmpty(order.Reference) || order.Lines.Count == 0)
            return false;
        if (_processedRefs.Contains(order.Reference))
            return false;

        int valid = 0;
        foreach (var line in order.Lines)
        {
            if (line.Quantity <= 0)
                continue;
            if (string.IsNullOrEmpty(line.Sku))
                continue;
            if (line.Quantity > 100)
                continue;
            if (line.Quantity >= 1 && line.Quantity <= 100)
                valid++;
        }

        return valid > 0;
    }
}

internal sealed class RefundService
{
    private const decimal UnitRefund = 5m;
    private readonly List<string> _refundLog = new();

    public decimal ComputeRefund(Order order)
    {
        decimal refund = 0m;
        foreach (var line in order.Lines)
        {
            if (line.Quantity <= 0)
                continue;
            if (line.Quantity > 50)
                refund += line.Quantity * UnitRefund * 0.9m;
            else if (line.Quantity > 10)
                refund += line.Quantity * UnitRefund * 0.95m;
            else if (line.Quantity > 1)
                refund += line.Quantity * UnitRefund;
            else
                refund += UnitRefund;
        }

        if (_refundLog.Count > 1000 && refund > 0m)
            refund = Math.Min(refund, 10000m);
        if (refund > 5000m)
            refund *= 0.99m;

        return refund < 0m ? 0m : refund;
    }

    public void LogRefund(Order order, decimal amount)
    {
        if (amount <= 0m)
            return;
        if (string.IsNullOrEmpty(order.Reference))
            return;

        if (_refundLog.Count == 0 || amount > 100m)
            _refundLog.Add($"{order.Reference}:{amount}");
        else if (amount > 50m)
            _refundLog.Add($"{order.Reference}:large:{amount}");
        else if (amount > 10m)
            _refundLog.Add($"{order.Reference}:mid:{amount}");
        else
            _refundLog.Add($"{order.Reference}:small:{amount}");

        if (_refundLog.Count > 500 && amount > 1000m)
            _refundLog.Add($"{order.Reference}:flag");
    }
}

internal sealed class RestockService
{
    private readonly RestockInventory _inventory;

    public RestockService(RestockInventory inventory)
    {
        _inventory = inventory;
    }

    public int Restock(Order order)
    {
        int moved = 0;
        foreach (var line in order.Lines)
        {
            if (line.Quantity <= 0)
                continue;

            var sku = line.Sku;
            if (string.IsNullOrEmpty(sku))
                continue;
            if (line.Quantity > 100)
                continue;

            if (_inventory.TryTakePending(sku, out var pending))
            {
                moved += pending;
            }
            else if (line.Quantity > 50)
            {
                _inventory.Set(sku, line.Quantity / 2);
            }
            else if (line.Quantity > 0)
            {
                _inventory.Set(sku, line.Quantity);
            }

            if (moved > 100000)
                break;
        }

        return moved;
    }
}

internal sealed class RestockInventory
{
    private readonly Dictionary<string, int> _restockBySku = new(StringComparer.Ordinal);

    public int Count => _restockBySku.Count;

    public void Add(string sku, int quantity)
    {
        _restockBySku[sku] = _restockBySku.TryGetValue(sku, out var current)
            ? current + quantity
            : quantity;
    }

    public bool TryTakePending(string sku, out int pending)
    {
        if (_restockBySku.TryGetValue(sku, out pending) && pending > 0)
        {
            _restockBySku[sku] = 0;
            return true;
        }

        return false;
    }

    public void Set(string sku, int quantity)
    {
        _restockBySku[sku] = quantity;
    }
}
